import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).parent))
from lib import *
E = []
def g(id, term, definition, related=(), cites=()):
    E.append({"kind": "glossary", "id": id, "term": term, "definition": definition, "related": list(related), "citations": list(cites)})
S = lambda ch, a, b=None: C("snell", ch, a, b)
B = lambda ch, a, b=None: C("berkowitz", ch, a, b)

g("g-ipsilateral", "Ipsilateral", "On the same side of the body as the lesion or the structure being discussed. Cerebellar signs, lower motor neuron cranial nerve palsies and Horner syndrome are ipsilateral to their lesion.", ["g-contralateral", "g-decussation"])
g("g-contralateral", "Contralateral", "On the opposite side of the body from the lesion. Corticospinal weakness, spinothalamic pain loss and cortical sensory loss are contralateral to lesions above the level at which their fibers cross.", ["g-ipsilateral", "g-decussation"])
g("g-decussation", "Decussation", "A crossing of fibers from one side of the neuraxis to the other. The main decussations are the pyramidal (corticospinal, cervicomedullary junction), the sensory (medial lemniscus, lower medulla), the spinothalamic (anterior white commissure, within the cord), the optic chiasm and the superior cerebellar peduncle (midbrain). Where a pathway crosses determines whether a lesion produces ipsilateral or contralateral signs.", ["g-ipsilateral", "g-contralateral", "g-crossed-syndrome"], [S(4, 143, 156)])
g("g-crossed-syndrome", "Crossed (alternating) brainstem syndrome", "A cranial nerve palsy on one side with long tract signs (weakness or sensory loss) on the opposite side of the body, produced by a single brainstem lesion that involves an uncrossed cranial nerve nucleus or fascicle together with corticospinal or sensory fibers that cross elsewhere. The cranial nerve names the level: III for the midbrain, VI or VII for the pons, XII for the medulla.", ["g-decussation", "g-upper-motor-neuron"], [B(9, 75, 82)])
g("g-upper-motor-neuron", "Upper motor neuron", "The neuron of the motor cortex or brainstem whose axon descends in the corticospinal, corticobulbar or other descending tracts to influence the lower motor neuron. Upper motor neuron lesions cause weakness with spasticity, hyperreflexia, clonus and an extensor plantar response, with little wasting.", ["g-lower-motor-neuron", "g-babinski-sign"], [S(4, 152, 160)])
g("g-lower-motor-neuron", "Lower motor neuron", "The anterior horn cell or cranial nerve motor neuron and its axon to the muscle. Lesions cause flaccid weakness, wasting, fasciculation, hypotonia and loss of the tendon reflex whose arc it forms.", ["g-upper-motor-neuron", "g-fasciculation", "g-motor-unit"], [S(4, 165, 167)])
g("g-motor-unit", "Motor unit", "One lower motor neuron and all the muscle fibers it innervates. Denervation and reinnervation change the size and shape of motor unit potentials on EMG: large in reinnervation, small and polyphasic in myopathy.", ["g-lower-motor-neuron", "g-fasciculation"])
g("g-fasciculation", "Fasciculation", "A visible twitch of a group of muscle fibers produced by spontaneous discharge of a single motor unit, a sign of lower motor neuron irritability or degeneration, most significant when combined with wasting and weakness.", ["g-lower-motor-neuron"])
g("g-spasticity", "Spasticity", "Velocity-dependent increase in muscle tone with a clasp-knife release, resulting from loss of descending inhibition (largely reticulospinal) after upper motor neuron lesions. Distinguished from the lead-pipe or cogwheel rigidity of basal ganglia disease, which is present throughout the range and independent of speed.", ["g-upper-motor-neuron", "g-rigidity"])
g("g-rigidity", "Rigidity", "Increased tone that is present throughout the range of passive movement and does not depend on velocity (lead-pipe), often with a ratchety cogwheel quality when tremor is superimposed. A sign of extrapyramidal disease, classically parkinsonism.", ["g-spasticity", "g-bradykinesia"])
g("g-bradykinesia", "Bradykinesia", "Slowness and progressive reduction in the amplitude of repetitive movements, the cardinal sign of parkinsonism, reflecting under-activation of the motor cortex by the basal ganglia–thalamic loop.", ["g-rigidity"])
g("g-babinski-sign", "Babinski sign (extensor plantar response)", "Extension of the big toe with fanning of the other toes when the lateral sole is stroked, indicating a corticospinal (upper motor neuron) lesion. Normal in infants before myelination of the corticospinal tract.", ["g-upper-motor-neuron"])
g("g-clonus", "Clonus", "Rhythmic involuntary contractions elicited by a sudden sustained stretch, typically at the ankle, indicating hyperexcitable stretch reflexes after an upper motor neuron lesion. More than a few beats is abnormal.", ["g-upper-motor-neuron", "g-spasticity"])
g("g-dermatome", "Dermatome", "The strip of skin supplied by the sensory fibers of one spinal nerve root. Key landmarks: C6 thumb, C7 middle finger, C8 little finger, T4 nipple, T10 umbilicus, L4 medial leg, L5 dorsum of the foot and big toe, S1 lateral foot.", ["g-myotome", "g-sensory-level"], [S(18, 507, 512)])
g("g-myotome", "Myotome", "The group of muscles supplied by one spinal root. Root weakness crosses peripheral nerve territories (C7: triceps and wrist flexors), whereas nerve weakness crosses root territories.", ["g-dermatome", "g-radiculopathy"])
g("g-sensory-level", "Sensory level", "The dermatomal boundary below which sensation is impaired in a spinal cord lesion. The level for pin-prick lies one or two segments below the actual lesion because spinothalamic fibers cross obliquely over that distance.", ["g-dermatome", "g-dissociated-sensory-loss"], [B(4, 41, 44)])
g("g-dissociated-sensory-loss", "Dissociated sensory loss", "Loss of pain and temperature with preservation of touch, vibration and position sense, or the reverse. It shows that the spinothalamic and lemniscal pathways, which travel separately in the cord and brainstem, have been affected differently, and points to a cord or lateral brainstem lesion rather than a nerve, thalamic or cortical one.", ["g-sensory-level", "g-syrinx"], [S(4, 143, 149)])
g("g-syrinx", "Syrinx (syringomyelia)", "A fluid cavity within the spinal cord, usually cervical and often associated with a Chiari malformation, that first destroys the pain fibers crossing in the anterior white commissure and produces a cape-like dissociated sensory loss.", ["g-dissociated-sensory-loss"])
g("g-radiculopathy", "Radiculopathy", "Disease of a spinal nerve root, typically from disc herniation or foraminal stenosis, producing pain, sensory loss and weakness in the dermatome and myotome of that root with loss of its reflex.", ["g-dermatome", "g-myotome", "g-plexopathy"])
g("g-plexopathy", "Plexopathy", "A lesion of the brachial or lumbosacral plexus, between the roots and the peripheral nerves, producing deficits broader than one nerve and not confined to one root, with reduced sensory nerve action potentials because the lesion is distal to the dorsal root ganglion.", ["g-radiculopathy", "g-mononeuropathy"])
g("g-mononeuropathy", "Mononeuropathy", "Disease of a single peripheral nerve, usually from compression at a known site (carpal tunnel, ulnar groove, fibular head), producing sensory and motor deficits in the nerve's territory only.", ["g-plexopathy", "g-polyneuropathy"])
g("g-polyneuropathy", "Polyneuropathy", "Generalized disease of the peripheral nerves. Length-dependent axonal neuropathies begin symmetrically in the toes and ascend in a stocking-glove pattern; demyelinating neuropathies produce proximal and distal weakness with areflexia and slowed conduction.", ["g-mononeuropathy"], [B(27, 283, 287)])
g("g-homunculus", "Homunculus", "The distorted map of the body on the primary motor and somatosensory cortex, with the leg on the medial surface (anterior cerebral territory), the trunk at the vertex and the arm, hand and face on the lateral convexity (middle cerebral territory). It explains why anterior cerebral infarcts weaken the leg and middle cerebral infarcts the face and arm.", ["g-somatotopy"], [S(8, 279, 286)])
g("g-somatotopy", "Somatotopy", "The orderly representation of body parts within a pathway or nucleus. In the corticospinal tract the arm fibers lie medial to the leg fibers in the cord, and in the posterior columns the leg fibers lie medially; such arrangements explain the order in which functions are lost by expanding lesions.", ["g-homunculus"])
g("g-retinotopy", "Retinotopy", "The orderly mapping of the retina, and hence the visual field, onto the visual pathway and cortex. Upper retinal (lower field) fibers stay superior in the radiation and cortex; the macula occupies the occipital pole.", ["g-homonymous-hemianopia"])
g("g-homonymous-hemianopia", "Homonymous hemianopia", "Loss of the same half of the visual field in both eyes, produced by a lesion behind the optic chiasm on the opposite side. Congruity increases and pupillary involvement disappears as the lesion moves from the optic tract to the occipital cortex.", ["g-retinotopy", "g-macular-sparing", "g-rapd"], [B(6, 47, 51)])
g("g-macular-sparing", "Macular sparing", "Preservation of the central few degrees of vision in a homonymous hemianopia, characteristic of occipital infarcts because the macular cortex at the occipital pole receives collateral supply from the middle cerebral artery.", ["g-homonymous-hemianopia"])
g("g-rapd", "Relative afferent pupillary defect (RAPD)", "Paradoxical dilation of one pupil when a light is swung onto it from the other eye, showing that the afferent light signal from that eye is weaker. It indicates an optic nerve, chiasmal or optic tract lesion and never causes anisocoria.", ["g-anisocoria", "g-light-near-dissociation"], [B(10, 83, 85)])
g("g-anisocoria", "Anisocoria", "Unequal pupils. Anisocoria greater in the dark indicates a sympathetic (Horner) lesion on the side of the smaller pupil; greater in the light, a parasympathetic lesion on the side of the larger pupil; equal in both, physiologic.", ["g-rapd", "g-horner-syndrome"])
g("g-light-near-dissociation", "Light-near dissociation", "Pupils that fail to constrict to light but constrict to a near target, produced by lesions of the pretectum (Parinaud, Argyll Robertson) or by aberrant regeneration in the ciliary ganglion (Adie).", ["g-rapd"])
g("g-horner-syndrome", "Horner syndrome", "Miosis, mild ptosis and, with central or preganglionic lesions, facial anhidrosis, from interruption of the uncrossed three-neuron sympathetic pathway to the eye anywhere from the hypothalamus to the carotid artery.", ["g-anisocoria"], [B(10, 85, 87)])
g("g-nystagmus", "Nystagmus", "Rhythmic involuntary oscillation of the eyes, named by the direction of the fast phase. Peripheral vestibular nystagmus is unidirectional, horizontal-torsional and suppressed by fixation; central nystagmus changes direction with gaze, may be vertical or purely torsional and is not suppressed.", ["g-vestibulo-ocular-reflex", "g-internuclear-ophthalmoplegia"], [B(12, 107, 112)])
g("g-vestibulo-ocular-reflex", "Vestibulo-ocular reflex (VOR)", "The three-neuron reflex that moves the eyes opposite to head rotation to keep gaze stable, tested at the bedside by the head impulse and oculocephalic maneuvers. Loss on one side (a corrective saccade after a head impulse) indicates a peripheral vestibular lesion.", ["g-nystagmus"])
g("g-internuclear-ophthalmoplegia", "Internuclear ophthalmoplegia (INO)", "Failure of adduction of one eye on lateral gaze with nystagmus of the abducting eye, with preserved convergence, from a lesion of the medial longitudinal fasciculus on the side of the eye that fails to adduct.", ["g-nystagmus"], [B(11, 99, 100)])
g("g-lacune", "Lacune", "A small deep infarct (under 15 mm) from occlusion of a single penetrating artery, most often in the internal capsule, thalamus, basal ganglia or pons, producing one of the classical lacunar syndromes without cortical signs.", ["g-watershed"], [B(7, 60, 63)])
g("g-watershed", "Watershed (borderzone)", "The territory at the boundary between two arterial supplies, where perfusion pressure is lowest and infarction occurs first during hypotension or upstream stenosis: between ACA and MCA on the superior frontal convexity, between MCA and PCA in the parieto-occipital region, and in the deep white matter.", ["g-lacune"])
g("g-penumbra", "Ischemic penumbra", "Brain tissue around an infarct core that is hypoperfused and non-functioning but still viable, and can be saved by reperfusion within a limited time; its extent is estimated by perfusion imaging or the mismatch between clinical deficit and infarct core.", ["g-lacune"])
g("g-herniation", "Herniation", "Displacement of brain from one intracranial compartment to another under pressure: subfalcine (cingulate under the falx), uncal (medial temporal lobe through the tentorial notch), central (diencephalon downward), tonsillar (cerebellar tonsils through the foramen magnum) and upward (cerebellum through the notch).", ["g-false-localizing-sign", "g-cushing-response"], [B(30, 270)])
g("g-false-localizing-sign", "False localizing sign", "A deficit that suggests a lesion at a site other than the true one, produced by displacement or generalized pressure: a sixth nerve palsy from raised intracranial pressure, or hemiparesis on the side of a mass from compression of the opposite cerebral peduncle against the tentorium (Kernohan notch).", ["g-herniation"])
g("g-cushing-response", "Cushing response", "Hypertension with bradycardia and irregular breathing produced by medullary ischemia when intracranial pressure approaches arterial pressure, a sign of impending brainstem compression.", ["g-herniation"])
g("g-papilledema", "Papilledema", "Swelling of both optic discs from raised intracranial pressure transmitted along the optic nerve sheaths. Vision is preserved until late, in contrast to the early visual loss of optic neuritis, and the blind spots are enlarged.", ["g-herniation"])
g("g-hydrocephalus", "Hydrocephalus", "Enlargement of the ventricles from obstruction of CSF flow (obstructive, non-communicating) or impaired absorption (communicating). The pattern of ventricular dilatation locates the block; obstructive hydrocephalus contraindicates lumbar puncture.", ["g-papilledema"], [S(16, 455, 459)])
g("g-aphasia", "Aphasia", "A disorder of language, not of speech mechanics, from a lesion of the dominant (usually left) hemisphere. Classified by fluency, comprehension and repetition: Broca (non-fluent, comprehension preserved), Wernicke (fluent, comprehension impaired), conduction (repetition impaired), global and transcortical (repetition preserved).", ["g-dysarthria", "g-apraxia"], [B(7, 54, 56)])
g("g-dysarthria", "Dysarthria", "Impaired articulation of speech with intact language, from weakness or incoordination of the muscles of speech: spastic (pseudobulbar), flaccid (bulbar), ataxic (cerebellar) or hypokinetic (parkinsonian).", ["g-aphasia"])
g("g-apraxia", "Apraxia", "Inability to perform a learned skilled movement on command despite intact strength, sensation and comprehension, from a lesion of the dominant parietal lobe or its connections to the premotor cortex.", ["g-aphasia", "g-agnosia"])
g("g-agnosia", "Agnosia", "Failure to recognize objects, faces or sounds despite intact primary perception, from lesions of the association cortex: visual agnosia (occipitotemporal), prosopagnosia (fusiform), astereognosis (parietal).", ["g-apraxia", "g-neglect"])
g("g-neglect", "Hemispatial neglect", "Failure to attend to or respond to stimuli on one side of space, usually the left after a right parietal lesion, with extinction on double simultaneous stimulation and often anosognosia. It is a disorder of attention, not of sensation.", ["g-agnosia"], [B(7, 53)])
g("g-ataxia", "Ataxia", "Incoordination of movement: cerebellar ataxia (dysmetria, intention tremor, dysdiadochokinesia, not worse with eyes closed) or sensory ataxia from loss of proprioception (worse with eyes closed, Romberg positive).", ["g-romberg-sign", "g-dysmetria"], [B(8, 67, 73)])
g("g-dysmetria", "Dysmetria", "Overshooting or undershooting a target during a reaching movement, seen in the finger-nose and heel-shin tests, a sign of cerebellar hemisphere dysfunction ipsilateral to the lesion.", ["g-ataxia"])
g("g-romberg-sign", "Romberg sign", "Marked worsening of balance when the eyes are closed while standing with the feet together, indicating loss of proprioceptive input (posterior columns or peripheral nerves) that vision was compensating for. It is not a cerebellar sign.", ["g-ataxia"])
g("g-chorea", "Chorea", "Irregular, flowing, unpredictable involuntary movements that flit from one body part to another, from dysfunction of the striatum and the indirect pathway (Huntington disease, Sydenham chorea, drugs).", ["g-ballismus", "g-dystonia"])
g("g-ballismus", "Ballismus", "Violent, large-amplitude flinging movements of the proximal limbs, usually on one side (hemiballismus), from a lesion of the contralateral subthalamic nucleus.", ["g-chorea"])
g("g-dystonia", "Dystonia", "Sustained or intermittent muscle contractions producing twisting movements and abnormal postures, from disordered basal ganglia output; may be focal, segmental or generalized.", ["g-chorea"])
g("g-tremor", "Tremor", "Rhythmic oscillation of a body part. Rest tremor (parkinsonism), postural and action tremor (essential tremor, physiological, thyrotoxic), intention tremor (cerebellar outflow) and Holmes tremor (rest, postural and intention combined, midbrain).", ["g-dysmetria"])
g("g-spinal-shock", "Spinal shock", "The transient loss of all reflex activity below an acute spinal cord lesion, with flaccidity, areflexia and an atonic bladder, lasting days to weeks before spasticity and hyperreflexia emerge.", ["g-upper-motor-neuron", "g-autonomic-dysreflexia"], [S(4, 167, 168)])
g("g-autonomic-dysreflexia", "Autonomic dysreflexia", "Paroxysmal hypertension with headache, sweating and bradycardia triggered by a noxious stimulus (typically bladder distension) below a spinal cord lesion above T6, from unmodulated sympathetic discharge.", ["g-spinal-shock"])
g("g-cauda-equina", "Cauda equina", "The bundle of lumbar and sacral nerve roots descending in the lumbar cistern below the conus medullaris (L1–L2). Compression produces a lower motor neuron, radicular picture with saddle anesthesia and late sphincter loss: a surgical emergency.", ["g-conus-medullaris"])
g("g-conus-medullaris", "Conus medullaris", "The tapered end of the spinal cord at L1–L2 containing the sacral segments; lesions produce early symmetric saddle anesthesia and sphincter failure with little leg weakness.", ["g-cauda-equina"])
g("g-lhermitte-sign", "Lhermitte sign", "An electric shock sensation down the spine and limbs on neck flexion, indicating a lesion of the cervical posterior columns, classically demyelination, also seen in B12 deficiency and cervical spondylosis.", ["g-dissociated-sensory-loss"])
g("g-uhthoff-phenomenon", "Uhthoff phenomenon", "Transient worsening of neurological symptoms, typically vision, with a rise in body temperature, because demyelinated fibers fail to conduct when warmed. Characteristic of multiple sclerosis.", ["g-lhermitte-sign"])
g("g-pseudobulbar-palsy", "Pseudobulbar palsy", "Spastic weakness of the muscles of speech and swallowing with a brisk jaw jerk and emotional lability, from bilateral upper motor neuron (corticobulbar) lesions, in contrast to the flaccid, wasted bulbar palsy of lower motor neuron disease.", ["g-upper-motor-neuron", "g-lower-motor-neuron"], [B(13, 119, 121)])
g("g-forehead-sparing", "Forehead sparing", "Preservation of forehead movement in a facial weakness, indicating an upper motor neuron (central) lesion, because the upper facial nucleus receives bilateral cortical input. A lower motor neuron lesion paralyzes the whole side of the face.", ["g-upper-motor-neuron", "g-lower-motor-neuron"], [B(13, 120, 124)])
g("g-hints", "HINTS examination", "Three bedside tests (Head Impulse, Nystagmus pattern, Test of Skew) that distinguish a peripheral from a central cause of acute vertigo; a normal head impulse, direction-changing nystagmus or skew deviation indicates a central lesion.", ["g-vestibulo-ocular-reflex", "g-nystagmus"], [B(12, 110, 112)])
g("g-mni-space", "MNI space", "A standard stereotaxic coordinate system based on averaged MRI templates from the Montreal Neurological Institute, with x (left–right), y (posterior–anterior) and z (inferior–superior) in millimeters from the anterior commissure. This atlas uses the MNI152NLin2009cAsym template; all meshes and slice positions are expressed in its RAS millimeter coordinates.", [])
g("g-arterial-territory", "Arterial territory", "The region of brain supplied by one artery. Infarct patterns follow territories, and the territory maps shown on the MRI slices in this atlas are population averages that vary between individuals, especially at the borders.", ["g-watershed"])
g("g-dwi", "Diffusion-weighted imaging (DWI)", "An MRI sequence sensitive to the restricted diffusion of water in cytotoxic edema, which shows acute infarcts as bright areas within minutes of onset, well before CT or conventional MRI change; also bright in abscess, epidermoid and highly cellular tumors.", ["g-flair"])
g("g-flair", "FLAIR", "Fluid-attenuated inversion recovery: a T2-weighted MRI sequence with the CSF signal suppressed, making periventricular and cortical lesions such as demyelinating plaques, edema and gliosis conspicuous.", ["g-dwi"])

write(E)
